    try {
      const res = await f(`https://api-anime.apipop.net/show?imdb=${imdb}&ver=100.0.0.0.&os=windows&app_id=T4P_ONL`);
      const data = _.chain(_.map(res))
          .map((value, key) => ({ season: key + 1, data: value }))
          .value()

      resolve(data);
    } catch (error) {
      const e = new Error(error);
      reject(e);
    }
  });
};

module.exports = {
  movies,
  shows,
  animeShows
};

